    // 技术知识库与业务分类独立：场景只引用下列稳定 ID，不重复维护技术定义。
    const techCatalog = {
      llm:{ label:"LLM", name:"大语言模型", category:"生成与理解模型", tone:"blue", definition:"根据上下文预测并生成语言内容的模型，擅长理解、改写、归纳和组织文本，但输出并非事实数据库查询结果。", mechanism:["将输入切分为模型可处理的片段","利用上下文计算后续内容的概率","逐步生成回答并按任务要求组织格式"], good:["输入是非结构化文字，需要摘要、草拟或解释","任务允许对生成内容进行核验","需要把多段信息整理成可读表达"], limits:["不能保证事实、数值或引用天然正确","涉及确定性规则、精确计算时应交给规则或系统查询","受上下文长度、输入质量和敏感信息治理约束"], contrast:"LLM负责语言理解与生成；RAG负责把外部资料带入上下文。要查实时业务数据，应先调用受控系统接口。" },
      rag:{ label:"RAG", name:"检索增强生成", category:"知识使用模式", tone:"indigo", definition:"先检索有权限的外部资料，再把相关片段提供给生成模型，使回答能依据当前知识并标注来源。", mechanism:["准备可检索且带权限的资料","按问题检索并筛选相关片段","将片段和问题一起交给模型生成","返回答案、依据与可追溯来源"], good:["答案依赖企业制度、文档或持续变化的知识","用户需要看到具体依据","不适合仅依赖模型参数记忆"], limits:["检索可能遗漏、误召回或拿到过期资料","有来源不等于推论一定正确","必须处理文档质量、访问权限和版本时效"], contrast:"RAG在推理时提供外部知识；微调主要改变模型参数中的行为或表达。两者可配合，但不能简单互替。" },
      workflow:{ label:"Workflow", name:"工作流编排", category:"任务编排方式", tone:"teal", definition:"把任务拆为预先设计的步骤、条件和人工节点，按明确顺序执行并记录状态。", mechanism:["定义触发条件和步骤顺序","在节点调用规则、模型或业务系统","根据条件分支、重试或转人工","记录过程与结果"], good:["流程边界清楚、顺序稳定","需要权限、审批、留痕和失败回退","多个系统动作必须按固定次序执行"], limits:["流程变化需要维护节点和分支","不适合把开放式探索硬塞进大量固定分支","工作流本身不保证节点输出正确"], contrast:"Workflow的路径主要由人预设；Agent可在约束内动态选择下一步。固定高风险流程通常优先用Workflow。" },
      agent:{ label:"Agent", name:"智能体", category:"任务编排方式", tone:"purple", definition:"以目标和约束为输入，让模型在执行中选择工具、观察结果并决定下一步的任务执行方式。", mechanism:["接收目标、权限与停止条件","模型选择下一步动作或工具","观察工具返回并修正计划","达到目标、触发人工确认或停止"], good:["任务路径难以完全预设","需要多轮查找、判断和调用不同工具","可限制可执行动作并监控中间步骤"], limits:["可能循环、误调用工具或放大错误","不宜让其独立提交付款、人事或法律等高风险决定","需要工具权限、预算上限、终止条件与日志"], contrast:"Agent的步骤可动态变化；Workflow的主干和分支事先确定。并非多步骤任务都需要Agent。" },
      ocr:{ label:"OCR", name:"光学字符识别", category:"感知与内容提取", tone:"orange", definition:"把图片或扫描件中的文字识别为可处理的字符；可由传统算法、深度学习或多模态模型实现。", mechanism:["图像预处理与版面定位","定位文字区域并识别字符","输出文字、位置和置信度","按业务字段校验与纠错"], good:["票据、证照、合同扫描件需要转为文字","需要批量提取版面中的字段","后续规则或人工可核对关键字符"], limits:["模糊、遮挡、手写和复杂表格会降低准确性","识别文字不等于理解条款含义","关键金额、身份与日期必须按风险核验"], contrast:"OCR重点是读出字符；CV可识别更广泛的图像对象；多模态模型可结合图文语义解释，但也会误读。" },
      asr_tts:{ label:"ASR/TTS", name:"语音识别与语音合成", category:"感知与内容提取", tone:"cyan", definition:"ASR把语音转成文字；TTS把文字转成语音，二者分别处理输入和输出通道。", mechanism:["采集并切分音频","ASR识别词句与时间位置","可将文本交给摘要或对话模型","需要语音回复时由TTS合成"], good:["会议、客服通话等内容先以语音存在","需要可搜索的转写稿或语音播报","可以管理录音授权与保存周期"], limits:["噪声、口音、术语和多人重叠会造成转写错误","转写不等于理解或事实确认","录音涉及告知、权限与敏感内容保护"], contrast:"ASR/TTS处理语音与文字的转换；LLM处理转写后的语义归纳或回答，不能把两者混为一项能力。" },
      cv:{ label:"CV", name:"计算机视觉", category:"感知与内容提取", tone:"cyan", definition:"从图像或视频中识别、定位或衡量视觉对象及其状态的模型能力。", mechanism:["采集并标注图像或视频","模型提取视觉特征","输出类别、位置或数量","依据置信度及业务规则复核"], good:["问题依赖外观、位置、缺陷或行为特征","有足够代表性的图像样本","现场采集条件相对稳定"], limits:["光照、角度、遮挡和样本分布变化会影响结果","图像识别不能直接证明业务原因","涉及人脸等敏感数据需要更严格治理"], contrast:"CV侧重视觉识别与测量；OCR是其中面向文字的专门任务；多模态模型进一步连接视觉和语言推理。" },
      multimodal:{ label:"多模态模型", name:"多模态理解模型", category:"生成与理解模型", tone:"cyan", definition:"联合处理文字、图像、音频等多种输入，并在同一任务中关联它们的语义。", mechanism:["编码不同模态的输入","对齐图文或音视频中的相关信息","结合任务指令生成判断或描述","对关键对象与字段做校验"], good:["问题同时依赖图像和文字上下文","版面、图表或现场照片难以只靠文字表达","需要跨媒介摘要或解释"], limits:["可能误看细节、数字和空间关系","模型判断不能替代高精度测量或法定鉴定","输入体积、隐私与计算成本通常高于纯文本"], contrast:"OCR主要把图中文字转写；多模态模型尝试理解图文关系。关键字段可先用OCR或专用模型再核验。" },
      predictive:{ label:"预测模型", name:"时间序列与业务预测", category:"统计学习与优化", tone:"green", definition:"利用历史数据和相关变量估计未来的数量、概率或趋势，并表达不确定性。", mechanism:["确定预测目标与时间粒度","整理历史、季节和外部变量","训练并回测预测模型","输出预测区间并持续监控偏差"], good:["有连续且可比的历史记录","未来决策依赖需求、现金流或交期估计","可用历史留出期验证误差"], limits:["突发事件和制度变化会导致历史失效","预测是估计，不是承诺或因果解释","样本稀疏时简单基线可能更可靠"], contrast:"预测模型以数值估计为主；LLM擅长解释和表达，不能仅凭生成文字替代经过回测的数值预测。" },
      anomaly:{ label:"异常检测", name:"异常模式识别", category:"统计学习与优化", tone:"amber", definition:"从历史分布、同类对象或预设基线中识别显著偏离的记录，供进一步核查。", mechanism:["定义比较对象与正常基线","计算偏离程度或异常分数","按风险阈值排序告警","由业务证据确认原因并回收误报"], good:["异常样本稀少但正常行为有规律","审核资源有限，需要先排序线索","能记录反馈来调节误报与漏报"], limits:["异常不等于违规或错误","基线漂移会造成大量误报","高风险处置不能仅凭异常分数自动定性"], contrast:"规则引擎核查已知、明确的条件；异常检测发现偏离常态的模式，但通常不能解释全部原因。" },
      matching:{ label:"推荐与匹配模型", name:"推荐、相似度与排序", category:"统计学习与优化", tone:"green", definition:"根据对象特征和历史反馈估计匹配程度，给候选项排序或推荐。", mechanism:["表示用户、岗位、资料或候选项特征","计算相似度或学习匹配分数","按约束排序候选项","用真实反馈检验质量和偏差"], good:["候选项多、需要优先级排序","有可解释的匹配维度或反馈数据","最终选择仍由业务人员确认"], limits:["历史偏差会被模型继承","高分不等于符合全部硬性条件","不能代替涉及个人权益的最终决定"], contrast:"规则筛选判断是否满足硬条件；匹配模型在合格候选中排序。LLM可解释理由，但不应凭文字直接生成无校验分数。" },
      optimization:{ label:"优化算法", name:"约束条件下的方案求解", category:"统计学习与优化", tone:"green", definition:"在目标函数和约束条件明确时，搜索资源分配、排程或补货等问题的较优方案。", mechanism:["定义目标，如成本或交付率","表达库存、预算和时间等约束","求解候选方案并检查可行性","比较情景并由业务方确认"], good:["目标与限制可以量化","需要在多个可行方案间权衡","业务可接受近似最优与人工调整"], limits:["错误的目标函数会优化错方向","输入预测失准会使方案失效","复杂问题可能需要近似算法和计算预算"], contrast:"预测模型估计未来会发生什么；优化算法在给定预测与约束下决定怎么安排资源。" },
      rules:{ label:"规则引擎", name:"确定性业务规则执行", category:"工程与自动化", tone:"slate", definition:"把明确的业务条件写成可执行规则，按相同输入给出可复现的判断或动作；本身不必使用AI。", mechanism:["维护条件、阈值和例外","读取结构化输入","执行条件判断","输出规则命中与版本依据"], good:["政策、金额阈值或资格条件明确","必须可审计和一致执行","错误成本高且例外可以枚举"], limits:["无法自行理解复杂歧义文本","规则膨胀后维护成本上升","变化的隐含模式要靠分析或模型发现"], contrast:"规则引擎执行确定条件；LLM可理解含糊表述并提出建议，但不能替代必须精确执行的规则。" },
      rpa:{ label:"RPA", name:"界面操作自动化", category:"工程与自动化", tone:"slate", definition:"按预设步骤模拟人在软件界面上的点击、输入和读取，常用于缺少稳定接口的重复操作。", mechanism:["识别界面元素和触发条件","执行预设点击与录入","读取结果并处理常见异常","记录执行日志并转人工"], good:["旧系统没有可用API","操作步骤固定且量大","界面和权限较稳定"], limits:["界面改版会使脚本失效","不能天然理解业务语义或保证数据正确","需要凭证保管、异常恢复和防重复执行"], contrast:"RPA模拟界面操作；Tool/API直接调用系统接口，通常更稳定。两者可与AI配合，但自身不是大模型能力。" },
      api:{ label:"Tool/API", name:"工具调用与系统接口集成", category:"工程与自动化", tone:"slate", definition:"通过受控接口读取或写入业务系统，使模型或工作流能使用经过授权的实时数据和动作。", mechanism:["定义可调用的系统功能与参数","校验身份、权限和输入","调用接口并处理超时或失败","记录结果、审计与幂等控制"], good:["答案需要实时业务数据","流程需要跨系统查询或提交","业务系统提供稳定接口与权限模型"], limits:["接口返回错误仍会影响结果","写入动作需要最小权限与确认","接口不可用时要有失败回退"], contrast:"Tool/API负责连接和执行，不负责语言理解；RPA在没有接口时操作界面；LLM只能在受控范围内选择或解释调用。" }
    };
    Object.assign(techCatalog, {
      gis:{ label:"GIS", name:"地理信息与空间分析", category:"工程与空间数据", tone:"slate", definition:"把对象的坐标、路网与区域边界组织为空间数据，支持位置查询、邻近关系和路径计算；本身不必使用AI。", mechanism:["采集并校验坐标和地图图层","建立空间索引与拓扑关系","执行叠加、距离或路径计算","返回位置、范围或路线"], good:["业务问题依赖地点、辖区、距离或路网","有可信地图、坐标和更新机制","空间结果可与预测或优化模型组合"], limits:["地图过期和定位误差会误导结果","GIS不能单独判断污染成因或交通事故责任","敏感位置数据需要权限和脱敏"], contrast:"GIS处理空间关系；预测模型估计未来数值，优化算法在空间约束下寻找方案。", io:"输入：坐标、路网、区域边界及属性；输出：空间查询结果、范围、距离或路径。" },
      graph:{ label:"知识图谱", name:"实体关系图谱", category:"知识组织模式", tone:"indigo", definition:"将实体、属性及其关系组织成可查询的图结构，用于追踪关联和依赖；图谱本身不等于大模型。", mechanism:["定义实体、关系和来源","从可信数据建立关系边","按路径或邻域查询关联","核实关系时效和证据"], good:["问题依赖多跳关系或上下游链路","需要解释关系来自何处","源数据能稳定标识实体"], limits:["错误实体消歧会产生假关联","相关关系不能直接证明因果","建设和更新成本随数据异构度上升"], contrast:"知识图谱显式存储实体关系；RAG检索文本片段。GraphRAG可结合两者，但不是所有图谱查询都需要生成模型。", io:"输入：实体、关系、属性和证据来源；输出：关联路径、邻域或候选关系。" },
      edge:{ label:"边缘AI", name:"边缘侧模型部署", category:"部署与工程能力", tone:"slate", definition:"将感知或推理模型部署在靠近设备的数据采集端，以满足低延迟、离线或数据不出场的需要；它是部署位置，不是一种模型。", mechanism:["选择可在本地设备运行的模型","在设备端采集并预处理数据","本地推理并执行安全规则","同步必要日志与模型版本"], good:["控制或告警需要低延迟","网络不稳定或原始视频不宜上传","设备具备足够算力和维护能力"], limits:["算力、功耗和存储受限","模型更新、版本回滚与设备安全要管理","边缘推理结果仍会误判，安全控制必须独立设计"], contrast:"边缘AI说明模型在哪里运行；CV说明处理什么视觉任务。两者可组合，不能互相替代。", io:"输入：设备端传感器或图像；输出：本地识别结果、告警或控制系统可消费的信号。" }
    });
    Object.entries({
      llm:"输入：文本指令与上下文；输出：生成文本或结构化草稿。", rag:"输入：问题和受控知识库；输出：附依据的回答与引用。", workflow:"输入：触发事件和流程数据；输出：节点状态、动作结果与审计记录。", agent:"输入：目标、约束和可用工具；输出：受控的工具动作、观察及任务结果。", ocr:"输入：文档影像；输出：字符、位置、字段及识别置信度。", asr_tts:"输入：语音或文字；输出：转写文本或合成语音。", cv:"输入：图像或视频；输出：对象类别、位置、缺陷或状态分数。", multimodal:"输入：图像、文本或音频组合；输出：跨模态描述、判断或结构化信息。", predictive:"输入：历史序列和相关变量；输出：未来数值、概率或预测区间。", anomaly:"输入：当前记录与正常基线；输出：异常分数、告警及可核查特征。", matching:"输入：对象特征、候选集和约束；输出：候选排序或匹配分数。", optimization:"输入：目标、资源和约束；输出：可行排程、路径或分配方案。", rules:"输入：结构化事实与规则版本；输出：确定性判断、命中依据或动作。", rpa:"输入：预设界面步骤与业务数据；输出：界面操作结果和日志。", api:"输入：经授权的接口参数；输出：业务系统数据或受控动作结果。"
    }).forEach(([id,io])=>{ techCatalog[id].io=io; });

    // 能力分类与颜色只在这里维护。AI 的“模型 / 任务 / 架构”是不同层级；灰色能力不因参与 AI 项目而变成 AI。
    const techMeta = {
      llm:["ai","模型","blue"], multimodal:["ai","模型","orange"], cv:["ai","模型与视觉任务","orange"], ocr:["ai","视觉识别任务","orange"],
      asr_tts:["ai","语音任务（旧场景兼容）","orange"], predictive:["ai","预测模型","green"], anomaly:["ai","检测模型","green"], matching:["ai","推荐模型","green"],
      rag:["ai","知识增强架构","indigo"], agent:["ai","动态执行架构","purple"],
      workflow:["digital","流程编排","slate"], rules:["digital","规则计算","slate"], rpa:["digital","界面自动化","slate"], api:["digital","系统集成","slate"],
      gis:["digital","空间计算","slate"], graph:["digital","知识工程","slate"], optimization:["digital","运筹优化","slate"], edge:["digital","部署工程","slate"]
    };
    Object.entries(techMeta).forEach(([id,[kind,layer,tone]])=>{Object.assign(techCatalog[id],{kind,layer,tone,role:techCatalog[id].good[0]});});
    techCatalog.ocr.label="AI OCR";
