    techCatalog.ocr.definition="以训练后的视觉模型定位并识别图像中的文字，输出可核验的字符、位置或字段；这是 OCR 的一种实现，不代表所有 OCR 都是 AI。";
    techCatalog.workflow.label="传统 Workflow";
    techCatalog.workflow.name="确定性工作流编排";
    techCatalog.api.label="API / 系统集成";
    techCatalog.graph.tone="slate";
    techCatalog.optimization.tone="slate";
    techCatalog.edge.kind="digital";

    function addTech(id,label,name,kind,layer,tone,definition,mechanism,io,good,limits,contrast,role) {
      techCatalog[id]={label,name,kind,layer,tone,category:layer,definition,mechanism:mechanism.split("→").map(s=>s.trim()),io,good:[good],limits:[limits],contrast,role};
    }
    // AI 模型与认知任务。任务能力可能由多种模型实现，不能把任务名当作模型架构。
    addTech("asr","ASR","自动语音识别","ai","语音任务","orange","把录音中的语音转换成带时间位置的文本，供检索、摘要或后续业务处理。","录音采集→降噪与切分→声学和语言解码→术语校正与置信度核验","音频 → 转写文本、时间戳、置信度","原始信息是会议或通话语音，后续需要文字处理。","噪声、方言和多人重叠会误转写；关键事实仍需听录音核对。","ASR负责语音转文字；TTS方向相反；LLM对转写内容做摘要或回答。","将语音资料转成可处理文本");
    addTech("tts","TTS","语音合成","ai","语音任务","orange","把文字转换成可播放的合成语音，作为人机交互的输出通道。","待播报文本→发音与韵律生成→音频合成→试听和安全检查","文本、音色参数 → 音频","需要语音播报、无障碍朗读或电话语音回复。","发音与语气可能不自然；不能凭声音自然就认定内容正确；需规范声音授权。","TTS只生成声音；ASR识别声音；LLM生成或改写播报文字。","把已确认内容播报给用户");
    addTech("nlu","自然语言理解","意图与语义理解","ai","认知任务","blue","从用户话语中识别意图、对象、条件和上下文，不特指一种模型结构。","输入话语→识别意图和实体→结合上下文消歧→输出语义表示","问题或对话 → 意图、实体和约束","用户以自然语言表达需求，系统需要路由或填表。","含糊表达可能被误解；涉及权限或金额时必须再核对结构化字段。","NLU是任务；LLM是可能的实现模型；规则词典也能处理简单固定命令。","把人话转换为业务可处理的请求");
    addTech("semantic_extract","语义信息抽取","含义与关系提取","ai","认知任务","blue","从非结构化内容中抽取业务含义、实体关系及事件，而非只复制文字。","阅读文本→识别实体和关系→映射业务字段→来源核验","文本 → 实体、关系和事件","合同、记录或反馈中存在跨句关联和隐含语义。","模型可能臆造关系；抽取结果需要证据片段与字段约束。","OCR负责读出字；语义抽取负责解释字的业务含义。","把材料转为可核查的业务事实");
    addTech("doc_parse","文档智能解析","版面和内容联合解析","ai","文档任务","orange","结合版面、文本与视觉结构，识别文档段落、表格、标题和字段。","文档输入→版面分区→文字与表格识别→结构重建→字段核验","PDF或图片 → 结构化文档元素","资料版式多变且上下文、表格位置影响含义。","扫描质量、跨页表格和复杂图纸会导致结构错误。","传统 OCR 主要输出文字；文档解析还恢复版面层级和表格关系。","为检索、审核和抽取提供结构化材料");
    addTech("structured_extract","结构化信息抽取","受约束的字段提取","ai","信息抽取任务","blue","按业务字段模式从文本或图像中提取值，并附来源与校验状态。","定义字段模式→识别候选值→格式与交叉校验→输出字段","材料和字段定义 → JSON或表单字段","需要从格式不一的资料中填写统一业务字段。","缺失字段不能猜补；金额、日期与身份应按规则复核。","语义抽取关注广泛关系；结构化抽取关注预定义字段和可落库格式。","把非结构化输入接入表单或系统");
    addTech("text_gen","文本与内容生成","受控业务文本生成","ai","生成任务","blue","根据明确输入和约束生成草稿、摘要或解释，最终内容需符合业务事实与规范。","组织事实与风格要求→模型生成→规则和来源检查→人工定稿","事实、要求 → 文案或报告草稿","文本表达量大、事实可提供且允许审阅。","可能产生虚构事实和不当措辞；不能代替审批或专业签发。","LLM是底层模型；文本生成是其承担的具体任务。","输出可供人修改的业务草稿");
    addTech("image_gen","图像生成","受约束的图片合成","ai","生成任务","orange","按文本、参考图或结构约束合成新图像，而非从图库精确取回原图。","商品及参考素材→生成图像→一致性与版权检查→人工选用","提示、参考图 → 候选图片","需快速制作创意草图或可审核的营销素材。","可能改动商品细节、品牌标识或人物；商用前须检验一致性与权利。","CV识别现有图像；图像生成创造候选内容。","生成待审核的视觉素材");
    addTech("video_gen","视频生成","视频片段合成","ai","生成任务","orange","根据脚本、图像或参考片段生成动态画面，供剪辑与审查。","脚本与镜头约束→视频生成→时序一致性检查→剪辑审核","脚本、参考素材 → 视频片段","需要短视频创意原型或可后期修订的内容。","动作、商品细节和时序可能失真，版权与真实性风险较高。","图像生成处理单帧；视频生成还须维持跨帧时序一致。","提供可编辑的视频初稿");
    addTech("ai_coding","AI辅助编程","代码生成与修改辅助","ai","开发任务","blue","模型根据代码库和需求建议代码、测试或解释，工程师验证后提交。","读取授权代码上下文→生成修改→运行测试→人工审查合并","需求与代码 → 代码补丁、测试建议","开发任务边界清楚且有可运行验证环境。","可能引入漏洞、错误依赖或不符合业务约束的实现；不得跳过审查。","AI Coding是开发任务；Spec Coding强调先形成可检查的规格再驱动实现。","帮助工程师起草和迭代代码");
    // AI 知识增强与应用架构。
    addTech("graphrag","GraphRAG","图结构增强检索生成","ai","知识增强架构","indigo","在检索生成链路中使用实体关系、图邻域或图摘要组织证据；实现方式并不唯一。","构建或利用图结构→按问题召回关系及原文→证据筛选→模型回答","问题、图与原文 → 关系依据和回答","问题需要跨实体、多跳关系或全局主题归纳。","图构建错误会传播；成本较高，未必优于普通 RAG。","知识图谱是数据组织结构；GraphRAG是利用图进行检索增强的应用方式。","为复杂关联问题提供结构化证据");
    addTech("multi_agent","Multi-Agent","多智能体协作","ai","任务编排架构","purple","让多个有分工的智能体交换中间结果并协作完成任务。","分解目标→分派角色和工具→交换与验证结果→合并输出","目标与角色约束 → 协作过程和结果","角色边界清楚且单 Agent 难以兼顾并行或相互校验。","通信成本和误差传播可能超过收益；不是比单 Agent 必然更高级。","单 Agent 独立规划；多 Agent 显式分工；固定流程可用普通 Workflow。","处理确需角色分工的复杂任务");
    addTech("ai_workflow","AI Workflow","含AI节点的固定业务工作流","ai","AI编排架构","purple","在预设步骤和条件分支中嵌入模型识别、生成或判断节点。","触发流程→系统取数→模型处理→规则校验→人工或系统流转","业务事件 → 节点结果与流程状态","主流程稳定，但某一步需要理解非结构化信息。","AI节点仍有不确定性，必须设计置信度、重试和人工回退。","传统 Workflow没有模型节点；Agent可动态选择下一步，AI Workflow主干预设。","把AI节点稳妥嵌入既有流程");
    addTech("tool_call","LLM Tool Calling","大模型受控工具调用","ai","AI编排架构","purple","模型选择预先授权的工具和参数，由应用程序执行并把结果返回模型。","模型提出调用→权限与参数校验→系统执行工具→模型读取结果","问题、工具模式 → 调用参数与处理结果","回答需实时查询或执行有限的系统动作。","模型可能选错工具或参数；高风险写入须人工授权和幂等控制。","API本身是工程接口；Tool Calling是模型决定何时调用接口的机制。","连接模型判断与受控外部动作");
    addTech("skill","AI Skill","任务能力封装","ai","AI应用封装","purple","把任务指令、资源、工具约束和验证步骤封装为可复用能力。","定义任务契约→装载资料与工具→执行步骤→检查输出","任务输入 → 符合契约的结果","同类任务反复出现，需要统一操作规范。","封装不能弥补错误知识或缺失权限，也不必依赖多 Agent。","Skill是能力封装单位；Agent是可动态决策的执行方式。","复用经过验证的任务做法");
    addTech("text_to_sql","Text-to-SQL","自然语言转数据库查询","ai","AI数据访问架构","blue","把自然语言问题映射到受控数据语义和 SQL，再由数据库执行查询。","理解问题→匹配字段与指标→生成 SQL→权限与语法校验→只读执行与核对","问题、数据字典 → SQL及查询结果","用户需要临时追问结构化业务数据。","可能选错表、口径或连接条件；需只读权限、限流、脱敏与结果校验。","BI报表回答预设指标；Text-to-SQL生成新查询，但不自动保证业务口径正确。","把业务提问转为可审核的数据查询");
    addTech("embedding","Embedding","语义向量表征","ai","知识检索组件","indigo","把文本等对象映射到向量空间，使语义相近内容便于近邻检索。","切分对象→向量编码→索引存储→按距离召回","文本等对象 → 向量与相似候选","关键词不同但语义相近，需要高召回检索。","相似度不等于事实正确或业务相关；权限和时效需另控。","Embedding负责初步向量召回；Rerank对候选做更精细排序。","为语义检索提供候选召回");
    addTech("rerank","Rerank","候选内容重排","ai","知识检索组件","indigo","对检索初步召回的候选，按问题与内容相关性再次排序。","初召回候选→逐项相关性评分→重排和阈值过滤","问题及候选 → 重排列表","初召回内容多，相关片段排位不稳定。","不能补回从未召回的正确内容；增加时延和成本。","Embedding偏召回；Rerank偏精选；两者都不是答案生成。","提高进入生成上下文的证据质量");
    addTech("semantic_search","语义检索","按含义查找资料","ai","知识检索模式","indigo","利用语义表征检索表达不同但含义接近的文档或记录。","问题编码→向量或混合检索→重排→返回原文出处","查询 → 相关资料列表","用户词汇与资料命名不一致，如物料别名和旧称。","相似物料可能规格不同；需要字段过滤、权限与人工确认。","传统搜索依赖词面匹配；语义检索可跨同义表达，但精确编码仍宜关键词匹配。","找到词面不一致的候选资料");
