    // 深化方案使用 B 类场景自身的稳定 ID；路径沿用场景目录并在执行步骤上标注实际技术。
    function industryFocus(domainId,sceneId,interview,pain,approach,limit,ai,prereq,boundary,expected,metrics,stepTags) {
      const domain=industryKnowledge.find(item=>item.id===domainId);
      const line=domain.lines.find(item=>item.ai.some(scene=>scene.id===sceneId));
      const scene=line.ai.find(item=>item.id===sceneId);
      const tags=stepTags.split(";").map(item=>item ? item.split(",") : []);
      return {key:`b:${domainId}:${sceneId}`,data:{line:line.name,interview,pain,traditional:{approach,limit},ai,
        path:scene.path.map((step,index)=>[step,tags[index]||[]]),prereq,boundary,value:{expected,metrics:metrics.split("；")}}};
    }
