    appendCaseScene("b:logistics","运输管理",{id:"b:logistics:truck-loading",name:"跨境货物装载方案优化",summary:"根据货物尺寸、车辆空间和装载约束给出可行摆放方案。",tech:["multimodal","optimization","api"],path:["测量货物与车辆","解析装载约束","专业算法求解装载方案","现场人员复核安全和执行"]});
    appendCaseScene("pmo","项目计划",{id:"pmo|研发协作规范与AI编程",name:"研发协作规范与AI编程",summary:"把需求规格、开发规范和测试反馈接入研发协作。",tech:["spec_coding","ai_coding","workflow"],path:["明确需求规格","AI辅助编码","工程师运行测试并审查","迭代规范"]});
