    // B 类剩余场景的建议方案：逐项维护业务动作与边界，不将案例访谈中未证实的方案写成已落地成果。
    const verticalDecisionSeeds={};
    function completeVertical(id,pain,traditional,limit,ai,prereq,boundary,metrics,stepTags) {
      if(scenarioDetails[id]) return; // 保留已深化的场景，尤其是有原始案例证据的内容。
      const ref=byScene.get(id);
      if(!ref) throw new Error(`未知垂直行业场景：${id}`);
      const metricList=metrics.split("；");
      const tags=stepTags.split(";").map(group=>group ? group.split(",") : []);
      if(tags.length!==ref.scene.path.length) throw new Error(`技术步骤数不匹配：${id}`);
      const chosenIndex=tags.findIndex((group,index)=>index>0 && group.some(techId=>techCatalog[techId]?.kind==="ai"));
      const decisionIndex=chosenIndex<0 ? Math.max(1,tags.findIndex(group=>group.length)) : chosenIndex;
      const coreTech=tags[decisionIndex].map(techId=>techCatalog[techId].label).join("、");
      const conditions=[];
      const usedTech=new Set(tags.flat());
      if(usedTech.has("rag")) conditions.push("知识索引应保留原文出处、生效版本和访问权限，更新不依赖每次用户提问重新建库");
      if(usedTech.has("predictive")||usedTech.has("anomaly")) conditions.push("历史数据须覆盖代表性工况，并在上线前回测及持续监控漂移");
      if(usedTech.has("ocr")||usedTech.has("cv")) conditions.push("采集质量与代表性样本须先验证，低置信结果应回看原件");
      if(usedTech.has("optimization")) conditions.push("硬约束、优先级与不可行时的回退方案须由业务负责人确认");
      if(usedTech.has("api")) conditions.push("现有系统接口需按最小权限调用并保留审计记录");
      const fullPrereq=`${[prereq,...conditions].join("；")}。`;
      verticalDecisionSeeds[id]=[{step:decisionIndex+1,techIds:tags[decisionIndex],
        basis:`${limit}。${ai}`,
        alternative:`${traditional}。如果已经能满足当前任务，应先复用；仅在上述局限经试点确认时增加所选能力。`,
        boundary}];
      scenarioDetails[id]={
        line:ref.line.name,
        interview:`以前${pain}。传统方式是${traditional}，但${limit}。我的建议是用${coreTech}：${ai}。效果看${metricList.slice(0,2).join("、")}，需试点验证。`,
        pain,traditional:{approach:traditional,limit},ai,
        path:ref.scene.path.map((step,index)=>[step,tags[index]]),
        prereq:fullPrereq,boundary,
        value:{expected:`预期改善${metricList.slice(0,2).join("与")}；目前是待验证的方案目标，没有企业实测数据。`,metrics:metricList}
      };
    }
