    // A 类企业通用场景沿用稳定 ID。流程由每条场景独立编写，避免按场景名称拼接通用占位文案。
    const enterpriseDecisionSeeds={};
    function completeEnterprise(id,pain,digital,limit,flow,prereq,boundary,metrics,stepTags){
      if(scenarioDetails[id]) return;
      const ref=byScene.get(id); if(!ref||ref.domain.systemId!=="enterprise") throw new Error(`未知企业场景：${id}`);
      const steps=flow.split(" → "), tags=stepTags.split(";").map(group=>group?group.split(","):[]);
      if(steps.length!==tags.length) throw new Error(`企业场景流程与技术不匹配：${id}`);
      const metricList=metrics.split("；");
      const chosen=tags.findIndex((group,index)=>index>0&&group.some(techId=>techCatalog[techId]?.kind==="ai"));
      const decisionIndex=chosen<0?Math.max(0,tags.findIndex(group=>group.length)):chosen;
      const coreTech=tags[decisionIndex].map(techId=>techCatalog[techId]?.label||techId).join("、")||"受控业务规则";
      const usedTech=new Set(tags.flat()),conditions=[];
      if(usedTech.has("rag"))conditions.push("索引须保留资料版本、原文出处和访问权限，定期更新而非每次提问重建");
      if(usedTech.has("predictive")||usedTech.has("anomaly"))conditions.push("历史数据须先回测并持续监测口径或分布变化");
      if(usedTech.has("ocr")||usedTech.has("cv"))conditions.push("影像质量与低置信字段的人工回查机制须验证");
      if(usedTech.has("api"))conditions.push("现有系统接口应最小授权并留审计记录");
      enterpriseDecisionSeeds[id]=[{step:decisionIndex+1,techIds:tags[decisionIndex],
        basis:`${limit}。因此建议：${flow.replaceAll(" → ","；")}。`,
        alternative:`${digital}。若已覆盖业务问题，应优先沿用，不为使用AI而替换。`,boundary}];
      scenarioDetails[id]={line:ref.line.name,
        interview:`过去${pain}。原有${digital}，但${limit}。我的建议是用${coreTech}：${flow.replaceAll(" → ","；")}。效果看${metricList.slice(0,2).join("、")}。`,
        pain,traditional:{approach:digital,limit},ai:flow.replaceAll(" → ","；"),
        path:steps.map((step,index)=>[step,tags[index]]),
        prereq:[prereq,...conditions].join("；")+"。",boundary,
        value:{expected:`预期改善${metricList.slice(0,2).join("与")}；为待试点验证的方案目标，并非已发生的提效数据。`,metrics:metricList}};
    }
