    // 用场景任务特征建立模式关联，保留多模式组合；不依据领域名称强行归类。
    function inferPatternIds(scene){
      const name=scene.name||"", ids=new Set(), tech=new Set(scene.tech||[]);
      const add=(id,re)=>{if(re.test(name))ids.add(id);};
      add("knowledge_qa",/问答|答疑|知识检索|政策咨询|制度咨询|法规检索|法条检索|操作指引|知识指引/);
      add("data_query",/数据问答|自然语言问数|数据查询|信息查询|房源查询|库存查询|订单查询|记录查询/);
      add("recognition",/识别|解析|提取|抽取|转写|票据|影像|图纸|证照/);
      add("analysis",/分析|归因|指标|报表|报告|总结|摘要|归纳|复盘|洞察|监测/);
      add("relation",/关系|关联|链路|上下游|追溯|依赖|传播|图谱/);
      add("review",/审核|审查|核对|核验|校核|预审|合规|风险提示|异常提示|异常识别|完整性|一致性|质检/);
      add("matching",/匹配|推荐|排序|评分|优先级|画像|相似|筛选/);
      add("prediction",/预测|预警|延期风险|逾期风险|流失风险|故障风险|趋势/);
      add("optimization",/优化|排程|调度|补货|资源配置|装载|路线规划|路径规划/);
      add("generation",/生成|起草|草拟|撰写|编制|文案|创作|草稿|辅助编程/);
      add("process",/办理|受理|审批|派单|分派|流转|请求分类|自动分类|交接|回填/);
      add("task_execution",/智能执行|自主研究|复杂招商研究|多步调查/);
      if(tech.has("rag"))ids.add("knowledge_qa");
      if(tech.has("text_to_sql"))ids.add("data_query");
      if(tech.has("graph")||tech.has("graphrag"))ids.add("relation");
      if(tech.has("optimization")||tech.has("constraint")||tech.has("linear_mip"))ids.add("optimization");
      if(tech.has("agent")&&(/研究|调查|多步|研判|执行/.test(name)))ids.add("task_execution");
      return [...ids];
    }
