    const stockAd=byScene.get("b:retail:stock-ad-link");if(stockAd){stockAd.scene.solutionPatternIds=stockAd.scene.solutionPatternIds.filter(id=>id!=="optimization");stockAd.scene.solutionPatternIds.push("recognition","review","process");}
