    function el(tag, className, textValue) {
      const node = document.createElement(tag);
      if (className) node.className = className;
      if (textValue !== undefined) node.textContent = textValue;
      return node;
    }
    function highlighted(node, value, query) {
      if (!query) { node.textContent = value; return; }
      const source = value.toLocaleLowerCase("zh-CN");
      const needle = query.toLocaleLowerCase("zh-CN");
      let offset = 0;
      while (offset < value.length) {
        const at = source.indexOf(needle, offset);
        if (at < 0) { node.append(document.createTextNode(value.slice(offset))); break; }
        if (at > offset) node.append(document.createTextNode(value.slice(offset, at)));
        node.append(el("mark", "", value.slice(at, at + query.length)));
        offset = at + query.length;
      }
    }
