    function clearAndFocus() { state.query=""; searchInput.value=""; clearSearch.hidden=true; render(); }
    const routePositions=new Map();let currentRoute="",routeTrail=[],routeIndex=-1;
    function parseRoute(hash){
      let parts;try{parts=(hash||"").replace(/^#/,"").split("/").filter(Boolean).map(decodeURIComponent);}catch{return "/overview";}
      if(parts[0]==="overview"&&parts.length===1)return "/overview";
      if(parts[0]==="patterns"&&parts.length===1)return "/patterns";
      if(parts[0]==="patterns"&&parts.length===2&&patternById.has(parts[1]))return `/patterns/${parts[1]}`;
      if(parts[0]==="business"&&byId.has(parts[1])&&(parts.length===2||parts.length===4&&parts[2]==="scene"&&byScene.has(parts[3])&&byScene.get(parts[3]).domain.id===parts[1]))return `/business/${encodeURIComponent(parts[1])}${parts.length===4?`/scene/${encodeURIComponent(parts[3])}`:""}`;
      if(parts[0]==="technology"&&(parts.length===1||parts.length===2&&["catalog","foundations","data","execution"].includes(parts[1])))return `/technology${parts.length===2?`/${parts[1]}`:""}`;
      if(parts[0]==="cases"&&(parts.length===1||parts.length===2&&caseStudies.some(item=>item.id===parts[1])))return `/cases${parts.length===2?`/${parts[1]}`:""}`;
      return "/overview";
    }
    function saveRoutePosition(){if(!currentRoute)return;routePositions.set(currentRoute,{pageY:window.scrollY,drawerY:state.patternDrawer?.drawer.querySelector(".pattern-drawer-scroll")?.scrollTop||0});}
    function applyRoute(path,source="navigation",trigger=null){
      if(path===currentRoute)return;
      saveRoutePosition();currentRoute=path;
      if(path==="/patterns"&&state.patternLibrary&&!state.query&&state.patternDrawer){closePatternDrawer();updateNav();return;}
      if(path.startsWith("/patterns/")&&state.patternLibrary&&!state.query){openPatternDrawer(path.slice(10),trigger||document.activeElement);if(source!=="navigation")state.patternDrawer.drawer.querySelector(".pattern-drawer-scroll").scrollTop=routePositions.get(path)?.drawerY||0;return;}
      if(state.patternDrawer)closePatternDrawer();
      state.selected=null;state.selectedScene=null;state.techLibrary=false;state.caseLibrary=false;state.patternLibrary=false;state.selectedPattern=null;state.selectedCase=null;state.query="";searchInput.value="";clearSearch.hidden=true;state.collapsed.clear();
      const parts=path.split("/").filter(Boolean).map(decodeURIComponent);
      if(parts[0]==="patterns")state.patternLibrary=true;
      else if(parts[0]==="business"){state.selected=parts[1];state.selectedScene=parts[3]||null;state.navExpanded[byId.get(parts[1]).systemId]=true;}
      else if(parts[0]==="technology"){state.techLibrary=true;state.techSubView=parts[1]||"catalog";}
      else if(parts[0]==="cases"){state.caseLibrary=true;state.selectedCase=parts[1]||null;}
      render();
      window.scrollTo(0,source==="navigation"?0:routePositions.get(path)?.pageY||0);
      if(parts[0]==="patterns"&&parts[1]){openPatternDrawer(parts[1],trigger);if(source!=="navigation")state.patternDrawer.drawer.querySelector(".pattern-drawer-scroll").scrollTop=routePositions.get(path)?.drawerY||0;}
    }
    function goRoute(path,{replace=false,trigger=null,preserveView=false}={}){
      if(path===currentRoute)return;
      if(preserveView){saveRoutePosition();currentRoute=path;}
      else applyRoute(path,"navigation",trigger);
      if(replace&&routeIndex>=0)routeTrail[routeIndex]=path;
      else {routeTrail=routeTrail.slice(0,routeIndex+1);routeTrail.push(path);routeIndex=routeTrail.length-1;}
      const nextHash=`#${path}`;if(replace)window.location.replace(nextHash);else window.location.hash=nextHash;
    }
    function navigate(id,selectedScene=null){goRoute(id?`/business/${encodeURIComponent(id)}${selectedScene?`/scene/${encodeURIComponent(selectedScene)}`:""}`:"/overview");}
    function openPatternLibrary(id=null,trigger=null){if(!id){goRoute("/patterns");return;}if(!currentRoute.startsWith("/patterns"))goRoute("/patterns");goRoute(`/patterns/${id}`,{trigger});}
