        decisions.forEach(decision=>{
          const item=el("div","decision-item");
          item.append(el("h4","",decision.techIds.map(id=>techCatalog[id].label).join(" + ")),
            labeledParagraph("选择依据：",decision.basis),
            labeledParagraph("替代方案与取舍：",decision.alternative),
            labeledParagraph("能力边界：",decision.boundary));
          list.append(item);
        });
        details.append(list,el("p","decision-status",caseId?"选型分析为建议；相关案例材料不等于此处取舍已在项目中验证。":"建议选型，尚未在具体企业环境中验证。"));
