      const contrast=el("section",""); contrast.append(el("h3","","6. 与相近技术的区别"),el("p","",tech.contrast)); body.append(contrast);
      const role=el("section",""); role.append(el("h3","","7. 在业务方案中的职责"),el("p","",tech.role)); body.append(role);
