      const q=query.toLocaleLowerCase("zh-CN"),patterns=solutionPatterns.filter(item=>`${item.name} ${item.summary} ${item.traits} ${item.minimal}`.toLocaleLowerCase("zh-CN").includes(q)),technologies=Object.entries(techCatalog).filter(([,item])=>`${item.label} ${item.name} ${item.definition}`.toLocaleLowerCase("zh-CN").includes(q));
      if(patterns.length){const section=textModule(`通用解决模式 · ${patterns.length}项`),row=el("div","study-links");patterns.forEach(item=>{const button=el("button","study-link",`${item.name}：${item.summary}`);button.type="button";button.addEventListener("click",()=>openPatternLibrary(item.id));row.append(button);});section.append(row);content.append(section);}
      if(technologies.length){const section=textModule(`技术能力 · ${technologies.length}项`),row=el("div","study-links");technologies.forEach(([id,item])=>{const button=el("button","study-link",`${item.label} · ${item.name}`);button.type="button";button.addEventListener("click",()=>openTech(id,button));row.append(button);});section.append(row);content.append(section);}
