        lines.forEach(line => { const row=el("div","result-line"), name=el("div","result-line-name"), ai=el("div","result-ai"); highlighted(name,`${domain.systemName} / ${domain.name} / ${line.name}`,query); line.ai.forEach(item=>{ const part=el("button","search-scene"); part.type="button"; highlighted(part,item.name,query); part.title=`${domain.systemName} / ${domain.name} / ${line.name} / ${item.name}`; part.addEventListener("click",()=>navigate(domain.id,item.id)); ai.append(part); }); row.append(name,ai); card.append(row); });
        content.append(card);
